sp_widget.client_script:
function() {

    var c = this;

    // =====================================================
    // INITIAL STATE
    // =====================================================

    c.question = '';
    c.loading = false;

    if (!c.data.messages) {
        c.data.messages = [];
    }


    // =====================================================
    // USER / SESSION STATE
    // =====================================================

    var authenticatedUserId = '';

    var userId = '';

    var HISTORY_PREFIX =
        'visaguardian_ai_history_';

    var ACTIVE_USER_KEY =
        'visaguardian_ai_active_user';

    var HISTORY_KEY =
        null;

    var userCheckTimer =
        null;

    var destroyed =
        false;


    // =====================================================
    // GET INITIAL USER ID
    //
    // IMPORTANT:
    // Server Script provides data.user_id using:
    //
    // gs.getUserID()
    //
    // We do NOT use the URL.
    // We do NOT use window.NOW.user_id.
    // =====================================================

    try {

        if (
            c.data &&
            c.data.user_id
        ) {

            userId =
                String(
                    c.data.user_id
                ).trim();

        }

    }
    catch (e) {

        userId = '';

    }


    // =====================================================
    // INITIAL USER ID
    // =====================================================

    if (userId) {

        authenticatedUserId =
            userId;

        HISTORY_KEY =
            HISTORY_PREFIX +
            userId;

    }


    // =====================================================
    // CLEAN VISIBLE TEXT
    // =====================================================

    function cleanVisibleText(text) {

        if (!text) {
            return '';
        }


        text =
            String(text);


        text =
            text.replace(
                /#[a-zA-Z0-9_-]+\s*\{[^}]*\}/g,
                ''
            );


        text =
            text.replace(
                /<style[\s\S]*?<\/style>/gi,
                ''
            );


        text =
            text.replace(
                /<script[\s\S]*?<\/script>/gi,
                ''
            );


        text =
            text.replace(
                /<[^>]+>/g,
                ''
            );


        text =
            text.replace(
                /\bGemini\s+AI\b/gi,
                ''
            );


        text =
            text.replace(
                /\bGemini\b/gi,
                ''
            );


        text =
            text.replace(
                /\bKnowledge\s+Base\b/gi,
                ''
            );


        text =
            text.replace(
                /[ \t]+/g,
                ' '
            );


        text =
            text.replace(
                /\n{3,}/g,
                '\n\n'
            );


        return text.trim();

    }


    // =====================================================
    // CLEAN OLD HISTORY
    // =====================================================

    function cleanHistoryMessages(history) {

        if (!Array.isArray(history)) {

            return [];

        }


        var cleaned = [];


        for (
            var i = 0;
            i < history.length;
            i++
        ) {

            var message =
                history[i];


            if (!message) {

                continue;

            }


            // Never restore searching messages.
            if (
                message.type === 'searching'
            ) {

                continue;

            }


            // Remove source messages.
            if (
                message.type === 'source' ||
                message.type === 'sources'
            ) {

                continue;

            }


            // =================================================
            // ANSWER
            // =================================================

            if (
                message.type === 'answer'
            ) {

                message.title =
                    'Visa Guidance';


                delete message.source;


                delete message.articles;


                message.articles = [];


                if (
                    message.introduction
                ) {

                    message.introduction =
                        cleanVisibleText(
                            message.introduction
                        );

                }


                if (
                    message.summary
                ) {

                    message.summary =
                        cleanVisibleText(
                            message.summary
                        );

                }


                if (
                    Array.isArray(
                        message.sections
                    )
                ) {

                    for (
                        var j = 0;
                        j < message.sections.length;
                        j++
                    ) {

                        var section =
                            message.sections[j];


                        if (
                            section.title
                        ) {

                            section.title =
                                cleanVisibleText(
                                    section.title
                                );

                        }


                        if (
                            section.text
                        ) {

                            section.text =
                                cleanVisibleText(
                                    section.text
                                );

                        }


                        if (
                            !Array.isArray(
                                section.bullets
                            )
                        ) {

                            section.bullets = [];

                        }


                        section.bullets =
                            section.bullets.map(
                                function(item) {

                                    return cleanVisibleText(
                                        item
                                    );

                                }
                            );


                        if (
                            !Array.isArray(
                                section.steps
                            )
                        ) {

                            section.steps = [];

                        }


                        section.steps =
                            section.steps.map(
                                function(item) {

                                    return cleanVisibleText(
                                        item
                                    );

                                }
                            );

                    }

                }


                message.showSources =
                    false;

                message.showSteps =
                    false;

            }


            // =================================================
            // ERROR
            // =================================================

            if (
                message.type === 'error'
            ) {

                message.text =
                    cleanVisibleText(
                        message.text
                    );

            }


            cleaned.push(
                message
            );

        }


        return cleaned;

    }


    // =====================================================
    // LOAD USER HISTORY
    // =====================================================

    function loadHistory() {

        // No valid authenticated user.
        if (!HISTORY_KEY) {

            c.data.messages = [];

            return;

        }


        try {

            var savedHistory =
                sessionStorage.getItem(
                    HISTORY_KEY
                );


            if (!savedHistory) {

                c.data.messages = [];

                return;

            }


            var history =
                JSON.parse(
                    savedHistory
                );


            if (
                Array.isArray(history)
            ) {

                c.data.messages =
                    cleanHistoryMessages(
                        history
                    );


                saveHistory();

            }
            else {

                c.data.messages = [];

            }

        }
        catch (e) {

            console.error(
                'VisaGuardian AI: Unable to load history',
                e
            );


            c.data.messages = [];

        }

    }


    // =====================================================
    // SAVE USER HISTORY
    // =====================================================

    function saveHistory() {

        // Never save without a verified user.
        if (!HISTORY_KEY) {

            return;

        }


        if (
            !Array.isArray(
                c.data.messages
            )
        ) {

            return;

        }


        try {

            var history = [];


            for (
                var i = 0;
                i < c.data.messages.length;
                i++
            ) {

                var message =
                    c.data.messages[i];


                // Never save loading indicator.
                if (
                    message.type === 'searching'
                ) {

                    continue;

                }


                // =================================================
                // ANSWER
                // =================================================

                if (
                    message.type === 'answer'
                ) {

                    var answer =
                        angular.copy(
                            message
                        );


                    answer.title =
                        'Visa Guidance';


                    answer.showSources =
                        false;


                    answer.showSteps =
                        false;


                    answer.articles =
                        [];


                    delete answer.source;


                    answer.introduction =
                        cleanVisibleText(
                            answer.introduction
                        );


                    answer.summary =
                        cleanVisibleText(
                            answer.summary
                        );


                    if (
                        Array.isArray(
                            answer.sections
                        )
                    ) {

                        answer.sections.forEach(
                            function(section) {

                                section.title =
                                    cleanVisibleText(
                                        section.title
                                    );


                                section.text =
                                    cleanVisibleText(
                                        section.text
                                    );


                                if (
                                    !Array.isArray(
                                        section.bullets
                                    )
                                ) {

                                    section.bullets =
                                        [];

                                }


                                section.bullets =
                                    section.bullets.map(
                                        function(item) {

                                            return cleanVisibleText(
                                                item
                                            );

                                        }
                                    );


                                if (
                                    !Array.isArray(
                                        section.steps
                                    )
                                ) {

                                    section.steps =
                                        [];

                                }


                                section.steps =
                                    section.steps.map(
                                        function(item) {

                                            return cleanVisibleText(
                                                item
                                            );

                                        }
                                    );

                            }
                        );

                    }


                    history.push(
                        answer
                    );

                }

                else {

                    history.push(
                        message
                    );

                }

            }


            sessionStorage.setItem(
                HISTORY_KEY,
                JSON.stringify(
                    history
                )
            );

        }
        catch (e) {

            console.error(
                'VisaGuardian AI: Unable to save history',
                e
            );

        }

    }


    // =====================================================
    // CLEAR CURRENT CHAT
    // =====================================================

    function clearCurrentChat() {

        c.data.messages = [];

        c.loading = false;

        c.question = '';

        try {

            if (HISTORY_KEY) {

                sessionStorage.removeItem(
                    HISTORY_KEY
                );

            }

        }
        catch (e) {

            console.error(
                'VisaGuardian AI: Unable to clear history',
                e
            );

        }

    }


    // =====================================================
    // CLEAR OLD USER HISTORY
    //
    // This removes only the previous user's history.
    // =====================================================

    function clearOldUserHistory(
        oldUserId
    ) {

        if (!oldUserId) {

            return;

        }


        try {

            sessionStorage.removeItem(
                HISTORY_PREFIX +
                oldUserId
            );

        }
        catch (e) {

            console.error(
                'VisaGuardian AI: Unable to remove old user history',
                e
            );

        }

    }


    // =====================================================
    // CHANGE ACTIVE USER
    // =====================================================

    function switchToUser(
        newUserId
    ) {

        newUserId =
            String(
                newUserId || ''
            ).trim();


        if (!newUserId) {

            return;

        }


        // =================================================
        // SAME USER
        // =================================================

        if (
            authenticatedUserId === newUserId
        ) {

            return;

        }


        var previousUserId =
            authenticatedUserId;


        console.log(
            'VisaGuardian AI: User changed from ' +
            previousUserId +
            ' to ' +
            newUserId
        );


        // =================================================
        // CRITICAL SECURITY STEP
        //
        // Immediately destroy the old student's
        // in-memory conversation.
        // =================================================

        c.data.messages = [];


        c.loading = false;


        c.question = '';


        // =================================================
        // Remove previous student's browser history.
        // =================================================

        clearOldUserHistory(
            previousUserId
        );


        // =================================================
        // Switch identity
        // =================================================

        authenticatedUserId =
            newUserId;


        userId =
            newUserId;


        HISTORY_KEY =
            HISTORY_PREFIX +
            newUserId;


        // =================================================
        // Store active authenticated user
        // =================================================

        try {

            sessionStorage.setItem(
                ACTIVE_USER_KEY,
                newUserId
            );

        }
        catch (e) {

            console.error(
                'VisaGuardian AI: Unable to update active user',
                e
            );

        }


        // =================================================
        // OPTIONAL:
        // Load this new student's own history.
        //
        // This will NEVER load the old student's history
        // because HISTORY_KEY now contains the new user's
        // actual ServiceNow sys_id.
        // =================================================

        loadHistory();


        scrollToBottom();

    }


    // =====================================================
    // VERIFY CURRENT USER WITH SERVER
    //
    // This is the MOST IMPORTANT FUNCTION.
    //
    // It calls the Server Script.
    //
    // Server Script uses:
    //
    // gs.getUserID()
    //
    // Therefore the browser cannot decide which student
    // is currently authenticated.
    // =====================================================

    function checkAuthenticatedUser() {

        if (destroyed) {

            return;

        }


        c.server.get({

            action:
                'get_current_user'

        }).then(

            function(response) {

                if (destroyed) {

                    return;

                }


                if (
                    !response ||
                    !response.data
                ) {

                    return;

                }


                var serverUserId =
                    String(
                        response.data.user_id || ''
                    ).trim();


                // =================================================
                // NOT LOGGED IN
                // =================================================

                if (!serverUserId) {

                    console.log(
                        'VisaGuardian AI: No authenticated user.'
                    );


                    c.data.messages = [];


                    c.loading = false;


                    c.question = '';


                    authenticatedUserId = '';


                    userId = '';


                    HISTORY_KEY = null;


                    return;

                }


                // =================================================
                // FIRST SERVER VERIFICATION
                // =================================================

                if (!authenticatedUserId) {

                    authenticatedUserId =
                        serverUserId;


                    userId =
                        serverUserId;


                    HISTORY_KEY =
                        HISTORY_PREFIX +
                        serverUserId;


                    try {

                        sessionStorage.setItem(
                            ACTIVE_USER_KEY,
                            serverUserId
                        );

                    }
                    catch (e) {}


                    loadHistory();


                    scrollToBottom();


                    return;

                }


                // =================================================
                // USER HAS CHANGED
                // =================================================

                if (
                    serverUserId !==
                    authenticatedUserId
                ) {

                    switchToUser(
                        serverUserId
                    );


                    return;

                }

            },

            function(error) {

                console.error(
                    'VisaGuardian AI: Server user validation failed',
                    error
                );

            }

        );

    }


    // =====================================================
    // INITIAL SERVER USER VALIDATION
    //
    // Do this immediately.
    // =====================================================

    checkAuthenticatedUser();


    // =====================================================
    // SCROLL TO BOTTOM
    // =====================================================

    function scrollToBottom() {

        setTimeout(
            function() {

                if (destroyed) {

                    return;

                }


                var chat =
                    document.getElementById(
                        'vg-chat'
                    );


                if (chat) {

                    chat.scrollTop =
                        chat.scrollHeight;

                }

            },
            100
        );

    }


    // =====================================================
    // CHECK USER EVERY 2 SECONDS
    //
    // This catches:
    //
    // Student A
    //     ↓
    // logout
    //     ↓
    // Student B
    //
    // even if Service Portal reuses the same widget/page.
    // =====================================================

    userCheckTimer =
        setInterval(
            function() {

                checkAuthenticatedUser();

            },
            2000
        );


    // =====================================================
    // ALSO CHECK USER WHEN TAB BECOMES ACTIVE
    // =====================================================

    try {

        document.addEventListener(
            'visibilitychange',
            function() {

                if (
                    !document.hidden
                ) {

                    checkAuthenticatedUser();

                }

            }
        );

    }
    catch (e) {

        console.error(
            'VisaGuardian AI: visibility listener error',
            e
        );

    }


    // =====================================================
    // SEND QUESTION
    // =====================================================

    c.sendQuestion =
        function() {

            // =============================================
            // DO NOT SEND IF ALREADY LOADING
            // =============================================

            if (
                c.loading
            ) {

                return;

            }


            // =============================================
            // MUST HAVE AUTHENTICATED USER
            // =============================================

            if (
                !authenticatedUserId
            ) {

                c.data.messages.push({

                    type:
                        'error',

                    text:
                        'Your login session could not be verified. Please refresh the page and try again.'

                });


                return;

            }


            var question =
                (
                    c.question ||
                    ''
                ).trim();


            if (!question) {

                return;

            }


            // =============================================
            // CRITICAL:
            // Capture the user who sent this request.
            //
            // If logout/login occurs while the request is
            // running, we will NOT allow the old response
            // into the new student's chat.
            // =============================================

            var requestUserId =
                authenticatedUserId;


            // =============================================
            // ADD USER MESSAGE
            // =============================================

            c.data.messages.push({

                type:
                    'user',

                text:
                    question,

                userId:
                    requestUserId

            });


            saveHistory();


            // =============================================
            // SEARCHING MESSAGE
            // =============================================

            c.data.messages.push({

                type:
                    'searching',

                text:
                    'Let me look up information related to ' +
                    question +
                    ' for you.',

                userId:
                    requestUserId

            });


            c.loading =
                true;


            var submittedQuestion =
                question;


            c.question =
                '';


            scrollToBottom();


            // =============================================
            // SERVER REQUEST
            // =============================================

            c.server.get({

                action:
                    'ask',

                question:
                    submittedQuestion

            }).then(

                function(response) {

                    // =====================================
                    // REMOVE SEARCHING MESSAGE
                    // =====================================

                    for (
                        var i =
                            c.data.messages.length - 1;
                        i >= 0;
                        i--
                    ) {

                        if (
                            c.data.messages[i].type ===
                            'searching'
                        ) {

                            c.data.messages.splice(
                                i,
                                1
                            );


                            break;

                        }

                    }


                    // =====================================
                    // CRITICAL USER CHECK
                    //
                    // If user changed while server was
                    // processing the request, discard the
                    // response completely.
                    // =====================================

                    if (
                        requestUserId !==
                        authenticatedUserId
                    ) {

                        console.log(
                            'VisaGuardian AI: Discarding response from previous user.'
                        );


                        c.loading =
                            false;


                        return;

                    }


                    // =====================================
                    // SUCCESS
                    // =====================================

                    if (
                        response &&
                        response.data &&
                        response.data.success
                    ) {

                        var sections =
                            response.data.sections ||
                            [];


                        sections =
                            normalizeSections(
                                sections
                            );


                        c.data.messages.push({

                            type:
                                'answer',

                            title:
                                response.data.title ||
                                'Visa Guidance',

                            introduction:
                                cleanVisibleText(
                                    response.data.introduction ||
                                    'Here are the key points related to your question:'
                                ),

                            sections:
                                sections,

                            summary:
                                cleanVisibleText(
                                    response.data.summary ||
                                    ''
                                ),

                            articles:
                                response.data.articles ||
                                [],

                            showSteps:
                                false,

                            showSources:
                                false,

                            userId:
                                requestUserId

                        });


                        saveHistory();

                    }

                    // =====================================
                    // SERVER ERROR
                    // =====================================

                    else {

                        var errorText =
                            (
                                response &&
                                response.data &&
                                response.data.error
                            ) ||
                            'I could not provide guidance for this question at the moment.';


                        c.data.messages.push({

                            type:
                                'error',

                            text:
                                cleanVisibleText(
                                    errorText
                                ),

                            userId:
                                requestUserId

                        });


                        saveHistory();

                    }


                    c.loading =
                        false;


                    scrollToBottom();

                },

                function(error) {

                    // =====================================
                    // REMOVE SEARCHING MESSAGE
                    // =====================================

                    for (
                        var i =
                            c.data.messages.length - 1;
                        i >= 0;
                        i--
                    ) {

                        if (
                            c.data.messages[i].type ===
                            'searching'
                        ) {

                            c.data.messages.splice(
                                i,
                                1
                            );


                            break;

                        }

                    }


                    // =====================================
                    // USER CHANGED?
                    // =====================================

                    if (
                        requestUserId !==
                        authenticatedUserId
                    ) {

                        c.loading =
                            false;


                        return;

                    }


                    c.data.messages.push({

                        type:
                            'error',

                        text:
                            'Unable to provide guidance right now. Please try again.',

                        userId:
                            requestUserId

                    });


                    c.loading =
                        false;


                    saveHistory();


                    scrollToBottom();

                }

            );

        };


    // =====================================================
    // NORMALIZE SECTIONS
    // =====================================================

    function normalizeSections(
        sections
    ) {

        if (
            !Array.isArray(
                sections
            )
        ) {

            return [];

        }


        var output = [];


        sections.forEach(
            function(section) {

                if (!section) {

                    return;

                }


                var newSection = {

                    title:
                        cleanVisibleText(
                            section.title ||
                            'Important Points'
                        ),

                    text:
                        cleanVisibleText(
                            section.text ||
                            ''
                        ),

                    bullets: [],

                    steps: []

                };


                // =====================================
                // BULLETS
                // =====================================

                if (
                    Array.isArray(
                        section.bullets
                    )
                ) {

                    section.bullets.forEach(
                        function(item) {

                            var clean =
                                cleanVisibleText(
                                    item
                                );


                            if (clean) {

                                newSection.bullets.push(
                                    clean
                                );

                            }

                        }
                    );

                }


                // =====================================
                // STEPS
                // =====================================

                if (
                    Array.isArray(
                        section.steps
                    )
                ) {

                    section.steps.forEach(
                        function(item) {

                            var clean =
                                cleanVisibleText(
                                    item
                                );


                            if (clean) {

                                newSection.steps.push(
                                    clean
                                );

                            }

                        }
                    );

                }


                // =====================================
                // TEXT TO BULLETS
                // =====================================

                if (
                    newSection.bullets.length === 0 &&
                    newSection.steps.length === 0 &&
                    newSection.text
                ) {

                    var points =
                        splitIntoPoints(
                            newSection.text
                        );


                    if (
                        points.length > 0
                    ) {

                        newSection.bullets =
                            points;


                        newSection.text =
                            '';

                    }

                }


                output.push(
                    newSection
                );

            }
        );


        return output;

    }


    // =====================================================
    // SPLIT TEXT INTO POINTS
    // =====================================================

    function splitIntoPoints(
        text
    ) {

        if (!text) {

            return [];

        }


        var lines =
            text.split(
                /\r?\n/
            );


        var points = [];


        lines.forEach(
            function(line) {

                line =
                    cleanVisibleText(
                        line
                    );


                line =
                    line.replace(
                        /^\s*(?:\d+[\.\)]|[-•*])\s*/,
                        ''
                    );


                if (line) {

                    points.push(
                        line
                    );

                }

            }
        );


        return points;

    }


    // =====================================================
    // ASK SUGGESTION
    // =====================================================

    c.askSuggestion =
        function(question) {

            if (!question) {

                return;

            }


            c.question =
                question;


            c.sendQuestion();

        };


    // =====================================================
    // ENTER KEY
    // =====================================================

    c.handleKeyPress =
        function(event) {

            if (
                event.which === 13 ||
                event.keyCode === 13
            ) {

                event.preventDefault();


                c.sendQuestion();

            }

        };


    // =====================================================
    // COPY ANSWER
    // =====================================================

    c.copyAnswer =
        function(message) {

            var text =
                'Visa Guidance\n\n';


            if (
                message.introduction
            ) {

                text +=
                    cleanVisibleText(
                        message.introduction
                    ) +
                    '\n\n';

            }


            if (
                Array.isArray(
                    message.sections
                )
            ) {

                message.sections.forEach(
                    function(section) {

                        if (
                            section.title
                        ) {

                            text +=
                                cleanVisibleText(
                                    section.title
                                ) +
                                '\n';

                        }


                        if (
                            section.text
                        ) {

                            text +=
                                cleanVisibleText(
                                    section.text
                                ) +
                                '\n';

                        }


                        if (
                            Array.isArray(
                                section.bullets
                            )
                        ) {

                            section.bullets.forEach(
                                function(item) {

                                    text +=
                                        '• ' +
                                        cleanVisibleText(
                                            item
                                        ) +
                                        '\n';

                                }
                            );

                        }


                        if (
                            Array.isArray(
                                section.steps
                            )
                        ) {

                            section.steps.forEach(
                                function(item) {

                                    text +=
                                        '• ' +
                                        cleanVisibleText(
                                            item
                                        ) +
                                        '\n';

                                }
                            );

                        }


                        text +=
                            '\n';

                    }
                );

            }


            if (
                message.summary
            ) {

                text +=
                    'Summary\n' +
                    cleanVisibleText(
                        message.summary
                    ) +
                    '\n';

            }


            try {

                if (
                    navigator.clipboard
                ) {

                    navigator.clipboard.writeText(
                        text
                    );

                }

            }
            catch (e) {

                console.error(
                    'VisaGuardian AI: Copy failed',
                    e
                );

            }

        };


    // =====================================================
    // FEEDBACK
    // =====================================================

    c.feedback =
        function(
            message,
            type
        ) {

            console.log(
                'VisaGuardian AI feedback:',
                type
            );

        };


    // =====================================================
    // CLEAR CHAT
    // =====================================================

    c.clearHistory =
        function() {

            clearCurrentChat();


            scrollToBottom();

        };


    // =====================================================
    // DESTROY CONTROLLER
    // =====================================================

    try {

        if (
            typeof $scope !==
            'undefined'
        ) {

            $scope.$on(
                '$destroy',
                function() {

                    destroyed =
                        true;


                    if (
                        userCheckTimer
                    ) {

                        clearInterval(
                            userCheckTimer
                        );


                        userCheckTimer =
                            null;

                    }

                }
            );

        }

    }
    catch (e) {

        console.error(
            'VisaGuardian AI: Controller cleanup error',
            e
        );

    }


    // =====================================================
    // INITIAL SCROLL
    // =====================================================

    setTimeout(
        function() {

            scrollToBottom();

        },
        300
    );

}

sp_widget.css:
/* =========================================================
   VISA GUARDIAN AI
   NOW ASSIST STYLE
   ========================================================= */

.vg-ai {

    width: 100%;

    background: #ffffff;

    color: #243746;

    font-family:
        "Segoe UI",
        Arial,
        sans-serif;

    border: 1px solid #d7e0e7;

    border-radius: 10px;

    overflow: hidden;

}


/* =========================================================
   HEADER
   ========================================================= */

.vg-header {

    height: 72px;

    padding: 0 24px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    background:
        linear-gradient(
            135deg,
            #073d70,
            #0c4d86
        );

    color: white;

}


.vg-header-left {

    display: flex;

    align-items: center;

    gap: 13px;

}


.vg-header-right {

    display: flex;

    align-items: center;

    gap: 18px;

}


.vg-bot-icon {

    width: 44px;

    height: 44px;

    border-radius: 50%;

    background: rgba(255,255,255,.15);

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;

}


.vg-title {

    font-size: 19px;

    font-weight: 600;

}


.vg-subtitle {

    margin-top: 3px;

    font-size: 11px;

    opacity: .8;

}


.vg-status {

    display: flex;

    align-items: center;

    gap: 7px;

    font-size: 12px;

}


.vg-status-dot {

    width: 8px;

    height: 8px;

    border-radius: 50%;

    background: #35d06f;

}


/* =========================================================
   CLEAR BUTTON
   ========================================================= */

.vg-clear-button {

    border: 1px solid rgba(255,255,255,.45);

    background: rgba(255,255,255,.08);

    color: white;

    padding: 7px 13px;

    border-radius: 6px;

    font-size: 12px;

    cursor: pointer;

    transition:
        background .2s ease,
        border-color .2s ease;

}


.vg-clear-button:hover {

    background: rgba(255,255,255,.18);

    border-color: rgba(255,255,255,.7);

}


/* =========================================================
   CHAT
   ========================================================= */

.vg-chat {

    min-height: 560px;

    max-height: 650px;

    overflow-y: auto;

    overflow-x: hidden;

    padding: 30px 46px 35px;

    background: #ffffff;

    scroll-behavior: smooth;

}


/* =========================================================
   BOT ROW
   ========================================================= */

.vg-bot-row {

    display: flex;

    align-items: flex-start;

    gap: 12px;

    margin-bottom: 12px;

}


.vg-small-avatar {

    width: 31px;

    height: 31px;

    min-width: 31px;

    border-radius: 50%;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #263f43;

    color: white;

    font-size: 13px;

}


.vg-welcome {

    max-width: 850px;

    font-size: 17px;

    line-height: 1.65;

}


.vg-welcome p {

    margin: 0;

}


/* =========================================================
   USER MESSAGE
   ========================================================= */

.vg-user-row {

    display: flex;

    justify-content: flex-end;

    margin: 25px 0 28px;

}


.vg-user-message {

    background: #ccebf4;

    color: #243746;

    padding: 10px 18px;

    border-radius:
        24px 24px 3px 24px;

    font-size: 15px;

    max-width: 65%;

    word-wrap: break-word;

    overflow-wrap: break-word;

}


/* =========================================================
   SEARCHING
   ========================================================= */

.vg-search-row {

    margin-top: 15px;

    margin-bottom: 20px;

}


.vg-search-text {

    padding-top: 5px;

    font-size: 16px;

    color: #344b57;

}


/* =========================================================
   AI LABEL
   ========================================================= */

.vg-ai-label {

    font-size: 16px;

    font-weight: 500;

    padding-top: 5px;

}


/* =========================================================
   AI STEPS
   ========================================================= */

.vg-ai-steps {

    margin-left: 43px;

    margin-bottom: 14px;

    max-width: 850px;

}


.vg-steps-button {

    width: 100%;

    border: none;

    background: transparent;

    padding: 7px 0;

    display: flex;

    align-items: center;

    gap: 9px;

    text-align: left;

    color: #334954;

    font-size: 15px;

    cursor: pointer;

}


.vg-chevron {

    margin-left: auto;

    font-size: 20px;

}


.vg-steps-content {

    margin-top: 7px;

    padding: 13px 16px;

    background: #f6f9fb;

    border-left: 3px solid #4b9bc1;

    border-radius: 4px;

}


.vg-step {

    display: flex;

    align-items: center;

    gap: 10px;

    padding: 7px 0;

    font-size: 12px;

    color: #637582;

}


.vg-step-number {

    width: 20px;

    height: 20px;

    min-width: 20px;

    border-radius: 50%;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #dcecf4;

    color: #34789a;

    font-size: 10px;

    font-weight: 700;

}


/* =========================================================
   RESPONSE
   ========================================================= */

.vg-response {

    margin-bottom: 40px;

}


/* =========================================================
   ANSWER
   ========================================================= */

.vg-answer-card {

    margin-left: 43px;

    max-width: 850px;

    word-wrap: break-word;

    overflow-wrap: break-word;

}


.vg-answer-card h2 {

    margin:
        12px 0 38px;

    font-size: 23px;

    line-height: 1.3;

    color: #263943;

    font-weight: 700;

}


.vg-introduction {

    font-size: 16px;

    line-height: 1.7;

    margin-bottom: 30px;

}


/* =========================================================
   SECTIONS
   ========================================================= */

.vg-section {

    margin-bottom: 27px;

}


.vg-section h3 {

    margin:
        0 0 15px;

    color: #243943;

    font-size: 18px;

    font-weight: 700;

}


.vg-section p {

    font-size: 16px;

    line-height: 1.75;

    margin:
        0 0 12px;

}


.vg-section ul,
.vg-section ol {

    padding-left: 27px;

    margin-top: 8px;

    margin-bottom: 15px;

}


.vg-section li {

    font-size: 16px;

    line-height: 1.75;

    padding-left: 4px;

    margin-bottom: 5px;

}


/* =========================================================
   SUMMARY
   ========================================================= */

.vg-summary {

    margin-top: 38px;

    padding-top: 25px;

    border-top:
        1px solid #e0e5e8;

}


.vg-summary h3 {

    margin:
        0 0 16px;

    font-size: 18px;

}


.vg-summary p {

    font-size: 16px;

    line-height: 1.75;

    margin: 0;

}


/* =========================================================
   SOURCES
   ========================================================= */

.vg-sources {

    margin-top: 30px;

}


.vg-source-button {

    border: none;

    background: transparent;

    color: #2b5368;

    cursor: pointer;

    display: flex;

    align-items: center;

    gap: 7px;

    font-size: 13px;

    padding: 5px 0;

}


.vg-source-list {

    margin-top: 10px;

    border-top:
        1px solid #e2e7eb;

}


.vg-source-item {

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 12px;

    border-bottom:
        1px solid #e7ecef;

}


.vg-source-icon {

    font-size: 18px;

}


.vg-source-details {

    display: flex;

    flex-direction: column;

    gap: 3px;

}


.vg-source-details strong {

    color: #567282;

    font-size: 11px;

}


.vg-source-details span {

    color: #254b60;

    font-size: 13px;

    font-weight: 600;

}


.vg-source-details small {

    color: #8798a2;

    font-size: 10px;

}


/* =========================================================
   FEEDBACK
   ========================================================= */

.vg-feedback {

    display: flex;

    gap: 17px;

    margin-top: 20px;

    padding-bottom: 15px;

}


.vg-feedback button {

    border: none;

    background: transparent;

    color: #5c727d;

    font-size: 17px;

    cursor: pointer;

    padding: 3px;

}


.vg-feedback button:hover {

    color: #1264a3;

}


/* =========================================================
   ERROR
   ========================================================= */

.vg-error {

    margin: 15px 40px;

    padding: 13px;

    border:
        1px solid #efb4b4;

    background: #fff3f3;

    color: #b83232;

    border-radius: 5px;

    line-height: 1.6;

}


/* =========================================================
   INPUT
   ========================================================= */

.vg-input-area {

    border-top:
        1px solid #dce3e8;

    padding:
        18px 35px 20px;

    background: #ffffff;

}


.vg-input-box {

    height: 58px;

    display: flex;

    border:
        1px solid #ccd9e0;

    border-radius: 12px;

    overflow: hidden;

    background: white;

}


.vg-input-box input {

    flex: 1;

    border: none;

    outline: none;

    padding:
        0 18px;

    font-size: 15px;

    color: #243746;

}


.vg-input-box input::placeholder {

    color: #8b9ba4;

}


.vg-input-box button {

    width: 65px;

    border: none;

    background: #1672a4;

    color: white;

    font-size: 20px;

    cursor: pointer;

    transition:
        background .2s ease;

}


.vg-input-box button:hover {

    background: #0e5b86;

}


.vg-input-box button:disabled {

    opacity: .6;

    cursor: not-allowed;

}


/* =========================================================
   DISCLAIMER
   ========================================================= */

.vg-disclaimer {

    text-align: center;

    margin-top: 8px;

    color: #8a9aa3;

    font-size: 10px;

}


/* =========================================================
   SCROLLBAR
   ========================================================= */

.vg-chat::-webkit-scrollbar {

    width: 7px;

}


.vg-chat::-webkit-scrollbar-track {

    background: #f3f5f6;

}


.vg-chat::-webkit-scrollbar-thumb {

    background: #c0ccd2;

    border-radius: 10px;

}


.vg-chat::-webkit-scrollbar-thumb:hover {

    background: #aebbc2;

}


/* =========================================================
   MOBILE
   ========================================================= */

@media screen and (max-width: 768px) {

    .vg-header {

        padding:
            0 15px;

    }


    .vg-header-right {

        gap: 8px;

    }


    .vg-status {

        display: none;

    }


    .vg-title {

        font-size: 16px;

    }


    .vg-subtitle {

        font-size: 10px;

    }


    .vg-chat {

        padding:
            25px 18px 30px;

    }


    .vg-answer-card {

        margin-left: 0;

    }


    .vg-ai-steps {

        margin-left: 0;

    }


    .vg-user-message {

        max-width: 85%;

    }


    .vg-input-area {

        padding:
            15px;

    }

}

sp_widget.script:
(function () {

    // =========================================================
    // VISAGUARDIAN AI
    // STUDENT AI CHAT SERVER SCRIPT
    // Service Portal Widget: VG AI Chat
    // =========================================================


    // =========================================================
    // CONFIGURATION
    // =========================================================

    /*
     * IMPORTANT:
     *
     * Replace this with the actual INTERNAL NAME of the
     * "Get Current Student Risk Assessment" Action Designer action.
     *
     * Example:
     * x_snc_visaguardi_0.get_current_student_risk_assessment
     *
     * Do NOT use the display label if your action has a different
     * internal name.
     */

    var RISK_ACTION_NAME =
        "x_snc_visaguardi_0.get_current_student_risk_assessment";


    // =========================================================
    // INITIAL DATA
    // =========================================================

    data.success = false;
    data.error = "";

    data.student = {};
    data.visa_case = {};
    data.advisor = {};
    data.documents = [];

    data.title = "VisaGuardian AI";
    data.introduction = "";
    data.sections = [];
    data.summary = "";
    data.articles = [];

    data.user_id = "";


    // =========================================================
    // CHECK LOGIN
    // =========================================================

    if (
        !gs.isLoggedIn() ||
        gs.getUserName() == "guest"
    ) {

        data.error =
            "Please log in to access VisaGuardian AI.";

        return;
    }


    // =========================================================
    // CURRENT LOGGED-IN USER
    // =========================================================

    var currentUserSysId =
        gs.getUserID();

    var currentUserName =
        gs.getUserName();

    data.user_id =
        currentUserSysId;


    // =========================================================
    // ASK QUESTION
    // =========================================================

    if (
        input &&
        input.action == "ask"
    ) {

        var question =
            String(
                input.question || ""
            ).trim();


        if (!question) {

            data.error =
                "Please enter a question.";

            return;
        }


        // =====================================================
        // GET CURRENT STUDENT
        // =====================================================

        var studentResult =
            getCurrentStudent(
                currentUserSysId
            );


        if (!studentResult.found) {

            data.error =
                "Your student profile could not be found.";

            return;
        }


        // =====================================================
        // LOAD CURRENT STUDENT DATA
        // =====================================================

        data.student =
            studentResult.student;


        // =====================================================
        // NO AUTOMATIC CASE SELECTION
        // =====================================================

        var caseResult = {

            found: false,

            caseSysId: "",

            case: {}

        };


        // =====================================================
        // ADVISOR STARTS EMPTY
        // =====================================================

        data.advisor = {

            name: "",

            email: ""

        };


        // =====================================================
        // DOCUMENTS START EMPTY
        // =====================================================

        data.documents = [];


        // =====================================================
        // NORMALIZE QUESTION
        // =====================================================

        var normalizedQuestion =
            question.toLowerCase();


        // =====================================================
        // PERSONAL STUDENT QUESTIONS
        // =====================================================


        // -----------------------------------------------------
        // MY EMAIL
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my email",
                    "my email address",
                    "what is my email",
                    "what's my email",
                    "what is my email address",
                    "what's my email address"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Email Address";

            data.introduction =
                "Here is your registered email address:";

            data.sections = [

                {
                    title: "Email",

                    text: "",

                    bullets: [

                        "Email: " +
                        safeValue(
                            data.student.email
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This email address belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY NAME
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my name",
                    "student name",
                    "who am i"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Name";

            data.introduction =
                "Here is your name:";

            data.sections = [

                {
                    title: "Student Name",

                    text: "",

                    bullets: [

                        "Name: " +
                        safeValue(
                            data.student.name
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY PHONE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my phone",
                    "my phone number",
                    "my mobile",
                    "my mobile number"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Phone Number";

            data.introduction =
                "Here is your registered phone number:";

            data.sections = [

                {
                    title: "Contact Information",

                    text: "",

                    bullets: [

                        "Mobile: " +
                        safeValue(
                            data.student.mobile_phone
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This contact information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY UNIVERSITY
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my university",
                    "what university do i attend",
                    "which university do i attend"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your University";

            data.introduction =
                "Here is your university information:";

            data.sections = [

                {
                    title: "University",

                    text: "",

                    bullets: [

                        "University: " +
                        safeValue(
                            data.student.university_name
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY DEGREE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my degree",
                    "my degree program",
                    "what is my degree",
                    "what am i studying"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Degree Program";

            data.introduction =
                "Here is your current degree information:";

            data.sections = [

                {
                    title: "Academic Information",

                    text: "",

                    bullets: [

                        "Degree Program: " +
                        safeValue(
                            data.student.degree_program
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY SEMESTER
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my semester",
                    "current semester",
                    "what semester am i in",
                    "which semester am i in",
                    "what is my current semester",
                    "what's my current semester"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Current Semester";

            data.introduction =
                "Here is your current semester information:";

            data.sections = [

                {
                    title: "Academic Information",

                    text: "",

                    bullets: [

                        "Current Semester: " +
                        safeValue(
                            data.student.current_semester
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY DETAILS / PROFILE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my details",
                    "my profile",
                    "my information",
                    "my student information",
                    "show my details",
                    "show my profile"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "My Student Information";

            data.introduction =
                "Here is your current student information:";

            data.sections = [

                {
                    title: "Student Information",

                    text: "",

                    bullets: [

                        "Name: " +
                        safeValue(
                            data.student.name
                        ),

                        "Student ID: " +
                        safeValue(
                            data.student.student_id
                        ),

                        "Email: " +
                        safeValue(
                            data.student.email
                        ),

                        "Mobile: " +
                        safeValue(
                            data.student.mobile_phone
                        ),

                        "University: " +
                        safeValue(
                            data.student.university_name
                        ),

                        "Degree Program: " +
                        safeValue(
                            data.student.degree_program
                        ),

                        "Current Semester: " +
                        safeValue(
                            data.student.current_semester
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // =====================================================
        // VISA QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my visa",
                    "visa status",
                    "visa type",
                    "sevis",
                    "sevis id",
                    "visa expiry",
                    "passport expiry",
                    "my immigration"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "My Visa Information";

            data.introduction =
                "Here is your current visa information:";

            data.sections = [

                {
                    title: "Visa Information",

                    text: "",

                    bullets: [

                        "Current Visa Status: " +
                        safeValue(
                            data.student.current_visa_status
                        ),

                        "Visa Type: " +
                        safeValue(
                            data.student.visa_type
                        ),

                        "SEVIS ID: " +
                        safeValue(
                            data.student.sevis_id
                        ),

                        "Visa Expiry Date: " +
                        safeValue(
                            data.student.visa_expiry_date
                        ),

                        "Passport Expiry Date: " +
                        safeValue(
                            data.student.passport_expiry_date
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information was retrieved for your currently logged-in student profile.";

            return;
        }


        // =====================================================
        // RISK ASSESSMENT
        // =====================================================

        if (
            isRiskAssessmentQuestion(
                normalizedQuestion
            )
        ) {

            var riskResult =
                getCurrentStudentRiskAssessment();


            if (
                riskResult.success
            ) {

                data.success = true;

                data.title =
                    "Student Risk Assessment";

                data.introduction =
                    "Here is your current operational risk assessment:";

                data.sections = [

                    {

                        title:
                            "Risk Assessment",

                        text: "",

                        bullets: [

                            "Risk Score: " +
                            safeValue(
                                riskResult.risk_score,
                                "Not available"
                            ) +
                            "/100",

                            "Risk Level: " +
                            safeValue(
                                riskResult.risk_level,
                                "Not available"
                            ).toUpperCase(),

                            "Why this score was assigned: " +
                            safeValue(
                                riskResult.risk_explanation,
                                "No explanation available."
                            )

                        ],

                        steps: []

                    }

                ];


                data.summary =
                    safeValue(
                        riskResult.risk_assessment_response,
                        "Your current risk assessment has been calculated."
                    );


                return;

            }


            data.success = true;

            data.title =
                "Risk Assessment";

            data.introduction =
                "I could not retrieve your current risk assessment.";

            data.sections = [

                {

                    title:
                        "Risk Assessment",

                    text: "",

                    bullets: [

                        "The risk assessment action could not be completed.",

                        "Please try again in a moment.",

                        "If the problem continues, contact your international student advisor."

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Your risk assessment could not be retrieved at this time.";

            return;
        }


        // =====================================================
        // CASE SUMMARY
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "summarize my case",
                    "summarize the case",
                    "summarize my visa case",
                    "can you summarize the visa case",
                    "summary of my case",
                    "summary of my visa case",
                    "give me a summary",
                    "give me the summary",
                    "give me summary",
                    "summarize my cases",
                    "summarize all my cases",
                    "summary of my cases",
                    "summary of all my cases",
                    "can you summarize my visa cases",
                    "can you summarize my cases",
                    "can you summarize my visa case",
                    "what should i do"
                ]
            )
        ) {

            var summaryCaseNumber =
                extractCaseNumber(
                    question
                );


            if (summaryCaseNumber) {

                var summaryCaseResult =
                    getVisaCaseByNumber(
                        summaryCaseNumber,
                        studentResult.profileSysId
                    );


                if (!summaryCaseResult.found) {

                    data.success = true;

                    data.title =
                        "Visa Case Summary";

                    data.introduction =
                        "I could not find " +
                        summaryCaseNumber +
