                }


                data.visa_case =
                    summaryCaseResult.case;


                data.advisor =
                    getAdvisor(
                        summaryCaseResult.case,
                        summaryCaseResult.caseSysId
                    );


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        summaryCaseResult.caseSysId,
