                ];

                data.summary =
                    "Review the case information and follow any outstanding requirements. For important immigration decisions, confirm requirements with your university international student advisor.";

                return;
            }


            var summaryCases =
                getStudentVisaCases(
                    studentResult.profileSysId
                );


            if (
                !summaryCases ||
                summaryCases.length === 0
            ) {

                data.success = true;

                data.title =
                    "Visa Case Summary";

                data.introduction =
                    "No visa cases were found for your student profile.";

                data.sections = [];

                data.summary =
                    "If you believe a case should exist, please contact your international student advisor.";

                return;
            }


            if (
                summaryCases.length === 1
            ) {

                var singleSummaryCase =
                    getVisaCaseByNumber(
                        summaryCases[0].case_id,
                        studentResult.profileSysId
                    );


                if (
                    singleSummaryCase.found
                ) {

                    data.visa_case =
                        singleSummaryCase.case;


                    data.advisor =
                        getAdvisor(
                            singleSummaryCase.case,
                            singleSummaryCase.caseSysId
                        );


                    data.documents =
                        getStudentDocuments(
                            studentResult.profileSysId,
                            singleSummaryCase.caseSysId,
                            singleSummaryCase.case.case_type_raw
                        );


                    var singleSummaryText =
                        buildCaseSummary(
                            data.student,
                            data.visa_case,
                            data.advisor,
                            data.documents
                        );


                    data.success = true;

                    data.title =
                        "AI Case Summary";

                    data.introduction =
                        "Here is a summary of your current visa case:";

                    data.sections = [

                        {

                            title:
                                "Case Summary",

                            text: "",

                            bullets:
                                convertToPoints(
                                    singleSummaryText
                                ),

                            steps: []

                        }

                    ];

                    data.summary =
                        "Review the case information and follow any outstanding requirements. For important immigration decisions, confirm requirements with your university international student advisor.";

                    return;
                }


                data.success = true;

                data.title =
                    "Visa Case Summary";

                data.introduction =
                    "I could not load your visa case.";

                data.sections = [];

                data.summary =
                    "Please try again or provide the case number.";

                return;
            }


            var overallSummaryText =
                buildAllCasesSummary(
                    data.student,
                    summaryCases
                );


            data.success = true;

            data.title =
                "AI Visa Case Summary";

            data.introduction =
                "Here is an overview of all visa cases associated with your student profile:";

            data.sections = [

                {

                    title:
                        "Visa Case Summary",

                    text: "",

                    bullets:
                        convertToPoints(
                            overallSummaryText
                        ),

                    steps: []

                }

            ];

            data.summary =
                "This summary covers all visa cases associated with your student profile. Review each case for outstanding actions and confirm important immigration requirements with your university international student advisor.";

            return;
        }


        // =====================================================
        // DOCUMENT QUESTIONS
        // =====================================================

        if (
            isDocumentQuestion(
                normalizedQuestion
            )
        ) {

            var documentCaseNumber =
                extractCaseNumber(
                    question
                );


            if (
                documentCaseNumber
            ) {

                var documentCaseResult =
                    getVisaCaseByNumber(
