                    );


                if (
                    !documentCaseResult.found
                ) {

                    data.success = true;

                    data.title =
                        "Document Access";

                    data.introduction =
                        "I could not find " +
                        documentCaseNumber +
                        " in your student profile.";

                    data.sections = [

                        {

                            title:
                                "Access Check",

                            text: "",

                            bullets: [

                                "The case number may be incorrect.",

                                "The case may not belong to the currently logged-in student.",

                                "For security, VisaGuardian only provides document information for your own visa cases."

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
