                    )

                );

            }


            data.success = true;

            data.title =
                "Choose a Visa Case";

            data.introduction =
                "You have multiple visa cases. Please tell me which case you want to check documents for:";

            data.sections = [

                {

                    title:
                        "Your Visa Cases",

                    text: "",

                    bullets:
                        documentCaseBullets,

                    steps: []

                }

            ];

            data.summary =
                "Please provide the case number, for example TASK12345.";

            return;
        }


        // =====================================================
        // CASE QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my case",
                    "visa case",
                    "case status",
                    "case stage",
                    "case priority",
                    "case type",
                    "case details",
                    "case information",
                    "my cases",
                    "all my cases",
                    "my visa cases",
                    "show my cases",
                    "list my cases",
                    "what are my cases",
                    "what visa cases do i have",
                    "current visa cases",
                    "what are my current visa cases"
                ]
            )
            ||
            extractCaseNumber(question)
        ) {

            var requestedCaseNumber =
                extractCaseNumber(
                    question
                );


            if (requestedCaseNumber) {

                var specificCaseResult =
                    getVisaCaseByNumber(
                        requestedCaseNumber,
                        studentResult.profileSysId
                    );


                if (!specificCaseResult.found) {

                    data.success = true;

                    data.title =
                        "Visa Case";

                    data.introduction =
                        "I could not find " +
                        requestedCaseNumber +
                        " in your student profile.";

                    data.sections = [

                        {

                            title:
                                "Case Access",

                            text: "",

                            bullets: [

                                "The case number may be incorrect.",

                                "The case may not belong to your student profile.",

                                "For security, VisaGuardian only provides access to your own visa cases."

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
                        "You can ask me to list your available visa cases.";

                    return;
                }


                caseResult =
                    specificCaseResult;


                data.visa_case =
                    caseResult.case;


                data.advisor =
                    getAdvisor(
                        caseResult.case,
                        caseResult.caseSysId
                    );


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        caseResult.caseSysId,
                        caseResult.case.case_type_raw
                    );


                data.success = true;

                data.title =
                    "My Visa Case";

                data.introduction =
                    "Here is the visa case you requested:";

                data.sections = [

                    {

                        title:
                            "Case Information",

                        text: "",

                        bullets: [

                            "Case ID: " +
                            safeValue(
                                data.visa_case.case_id
                            ),

                            "Case Type: " +
                            safeValue(
                                data.visa_case.case_type
                            ),

                            "Visa Category: " +
                            safeValue(
                                data.visa_case.visa_category
                            ),

                            "Priority: " +
                            safeValue(
                                data.visa_case.priority
                            ),

                            "Status: " +
                            safeValue(
                                data.visa_case.case_stage
                            ),

                            "Assigned Advisor: " +
                            safeValue(
                                data.advisor.name,
                                "Not Assigned"
                            ),

                            "Created On: " +
                            safeValue(
                                data.visa_case.created_on
                            ),

                            "Last Updated: " +
                            safeValue(
                                data.visa_case.updated_on
                            )

                        ],

                        steps: []

                    }

                ];

                data.summary =
                    safeValue(
                        data.visa_case.description,
                        "Your selected visa case information is shown above."
                    );

                return;
            }


            var studentCases =
                getStudentVisaCases(
                    studentResult.profileSysId
                );


            if (
                !studentCases ||
                studentCases.length === 0
            ) {

                data.success = true;

                data.title =
                    "My Visa Cases";

                data.introduction =
                    "I could not find any visa cases associated with your student profile.";

                data.sections = [];

                data.summary =
                    "If you believe you should have a visa case, please contact your international student advisor.";

                return;
            }


            var caseBullets = [];


            for (
                var c = 0;
                c < studentCases.length;
                c++
            ) {

                var currentCase =
                    studentCases[c];


                caseBullets.push(

                    (c + 1) +
                    ". " +
                    safeValue(
                        currentCase.case_id,
                        "Unknown Case"
                    ) +
                    " — Type: " +
                    safeValue(
                        currentCase.case_type,
