                    ) +
                    " — Status: " +
                    safeValue(
                        currentCase.case_stage,
                        "Not available"
                    )

                );

            }


            data.success = true;

            data.title =
                "My Visa Cases";

            data.introduction =
                "I found the following visa cases associated with your student profile:";

            data.sections = [

                {

                    title:
                        "Available Visa Cases",

                    text: "",

                    bullets:
                        caseBullets,

                    steps: []

                }

