            data.summary =
                "Please tell me the case number you want to view, for example TASK0020673.";

            return;
        }


        // =====================================================
        // ADVISOR QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my advisor",
                    "assigned advisor",
                    "who is my advisor",
                    "advisor name",
                    "advisor email",
                    "my advisors",
                    "show my advisors",
                    "assigned advisors",
                    "show assigned advisors"
                ]
            )
        ) {

            var advisorCaseNumber =
                extractCaseNumber(
                    question
                );


            if (advisorCaseNumber) {

                var advisorCaseResult =
                    getVisaCaseByNumber(
                        advisorCaseNumber,
