                    data.advisor =
                        getAdvisor(
                            advisorCaseResult.case,
                            advisorCaseResult.caseSysId
                        );

                }

            }
            else {

                var advisorCases =
                    getStudentVisaCases(
                        studentResult.profileSysId
                    );


                if (
                    !advisorCases ||
                    advisorCases.length === 0
                ) {

                    data.success = true;

                    data.title =
                        "My Advisor";

                    data.introduction =
                        "No visa cases were found in your student profile.";

                    data.sections = [];

                    data.summary =
                        "There are no case-specific advisors to display.";

                    return;
                }


                if (
                    advisorCases.length == 1
                ) {

                    var advisorOnlyCase =
                        getVisaCaseByNumber(
                            advisorCases[0].case_id,
                            studentResult.profileSysId
                        );


                    if (
                        advisorOnlyCase.found
                    ) {

                        data.visa_case =
                            advisorOnlyCase.case;

                        data.advisor =
                            getAdvisor(
                                advisorOnlyCase.case,
                                advisorOnlyCase.caseSysId
                            );

                    }


                    data.success = true;

                    data.title =
                        "My Advisor";

                    data.introduction =
                        "Here is the advisor assigned to your visa case:";

                    data.sections = [

                        {

                            title:
                                "Advisor Information",

                            text: "",

                            bullets: [

                                "Case Number: " +
                                safeValue(
                                    data.visa_case.case_id
                                ),

                                "Advisor Name: " +
                                safeValue(
                                    data.advisor.name,
                                    "Not Assigned"
                                ),

                                "Advisor Email: " +
                                safeValue(
                                    data.advisor.email,
                                    "Not Available"
                                )

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
                        "Advisor information is based on the advisor assigned to your visa case.";

                    return;
                }


                if (
                    advisorCases.length > 1
                ) {

                    var advisorCaseBullets = [];


                    for (
                        var ac = 0;
                        ac < advisorCases.length;
                        ac++
                    ) {

                        var currentAdvisorCase =
                            advisorCases[ac];


                        var advisorName =
                            safeValue(
                                currentAdvisorCase.assigned_advisor_name,
                                "Not Assigned"
                            );


                        var advisorEmail =
                            safeValue(
                                currentAdvisorCase.assigned_advisor_email,
                                ""
                            );


                        var advisorLine =

                            (ac + 1) +
                            ". " +
                            safeValue(
                                currentAdvisorCase.case_id,
                                "Unknown Case"
                            ) +
                            " — Type: " +
                            safeValue(
                                currentAdvisorCase.case_type,
                                "Not available"
                            ) +
                            " — Advisor: " +
                            advisorName;


                        if (
                            advisorEmail &&
                            advisorEmail != "Not available"
                        ) {

                            advisorLine +=
                                " — Email: " +
                                advisorEmail;

                        }


                        advisorLine +=
                            " — Status: " +
                            safeValue(
                                currentAdvisorCase.case_stage,
                                "Not available"
                            );


                        advisorCaseBullets.push(
                            advisorLine
                        );

                    }


                    data.success = true;

                    data.title =
                        "My Visa Advisors";

                    data.introduction =
                        "Here are the advisors assigned to your visa cases:";

                    data.sections = [

                        {

                            title:
                                "Your Visa Cases and Advisors",

                            text: "",

                            bullets:
                                advisorCaseBullets,

                            steps: []

                        }

                    ];

                    data.summary =
                        "The advisor information shown above is based on the advisor assigned to each visa case.";

                    return;
                }

            }


            data.success = true;

            data.title =
                "My Advisor";

            data.introduction =
                "Here is your currently assigned advisor information:";

            data.sections = [

                {

                    title:
                        "Advisor Information",

                    text: "",

                    bullets: [

                        "Advisor Name: " +
                        safeValue(
                            data.advisor.name,
                            "Not Assigned"
                        ),

                        "Advisor Email: " +
                        safeValue(
                            data.advisor.email,
                            "Not Available"
                        )

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Advisor information is based on the advisor assigned to the selected visa case.";

            return;
        }


        // =====================================================
        // KNOWLEDGE BASE
        // =====================================================

        var kbResult =
            searchKnowledgeBase(
                question
            );


        if (kbResult.found) {

            data.success = true;

            data.title =
                "Visa Guidance";

            data.introduction =
                "Here are the key points related to your question:";

            data.sections =
                kbResult.sections;

            data.summary =
                kbResult.summary;

            data.articles = [];

            return;
        }


        // =====================================================
        // GEMINI FALLBACK
        // =====================================================

        var aiResult =
            callGemini(
                question,
                data.student,
                data.visa_case,
                data.advisor,
                data.documents
            );


        if (aiResult.success) {

            data.success = true;

            data.title =
                "Visa Guidance";

            data.introduction =
                "Here are the key points related to your question:";

            data.sections = [

                {

                    title:
                        "Important Points",

                    text: "",

                    bullets:
                        convertToPoints(
                            aiResult.answer
                        ),

                    steps: []

                }

            ];

            data.summary =
                "For important immigration decisions, confirm requirements with your university international student advisor or the appropriate immigration authority.";

            data.articles = [];

            return;
        }


        // =====================================================
        // CREATE SUPPORT TICKET
        // =====================================================

        var ticketResult =
            createSupportTicket(
                studentResult.profileSysId,
                question
            );


        if (ticketResult.success) {

            data.success = true;

            data.title =
                "Support Request Created";

            data.introduction =
                "I couldn't find a direct answer to that, so I've created a support ticket for your advisor to review.";

            data.sections = [

                {

                    title:
                        "Ticket Details",

                    text: "",

                    bullets: [

                        "Ticket Number: " +
                        safeValue(
                            ticketResult.ticketNumber
                        ),

                        "Your Question: " +
                        question

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Your international student advisor will follow up on this ticket.";

            return;
        }


        // =====================================================
        // ERROR
        // =====================================================

        data.success = false;

        data.error =
            "I could not provide guidance for this question, and I was unable to create a support ticket automatically. Please contact your international student advisor directly.";

    }


    // =========================================================
    // GET CURRENT STUDENT RISK ASSESSMENT
    // =========================================================

    function getCurrentStudentRiskAssessment() {

        var result = {

            success: false,

            risk_score: 0,

            risk_level: "",

            risk_explanation: "",

            risk_assessment_response: "",

            error: ""

        };


        try {

            /*
             * The Action Designer action resolves the current
             * logged-in student itself.
             *
             * Therefore we intentionally do NOT send the
             * student sys_id from the browser.
             */

            var actionInputs = {};


            var actionResult =
                sn_fd.FlowAPI
                    .getRunner()
                    .action(
                        RISK_ACTION_NAME
                    )
                    .inForeground()
                    .withInputs(
                        actionInputs
                    )
                    .run();


            var outputs =
                actionResult.getOutputs();


            if (!outputs) {

                result.error =
                    "Risk assessment action returned no outputs.";

                return result;
            }


            result.risk_score =
                outputs["risk_score"];


            result.risk_level =
                outputs["risk_level"];


            result.risk_explanation =
                outputs["risk_explanation"];


            result.risk_assessment_response =
                outputs["risk_assessment_response"];


            /*
             * Make sure the action actually returned the
             * expected values.
             */

            if (
                result.risk_score === undefined &&
                result.risk_level === undefined &&
                result.risk_explanation === undefined &&
                result.risk_assessment_response === undefined
            ) {

                result.error =
                    "Risk assessment action returned unexpected outputs.";

                return result;
            }


            result.success = true;

            return result;

        }
        catch (e) {

            result.error =
                e.message ||
                String(e);


            gs.error(
                "VisaGuardian Risk Assessment Error: " +
                result.error
            );


            return result;
        }

    }


    // =========================================================
    // RISK QUESTION DETECTOR
    // =========================================================

    function isRiskAssessmentQuestion(
        normalizedQuestion
    ) {

        if (!normalizedQuestion) {

            return false;

        }


        return containsAny(
            normalizedQuestion,
            [

                "my risk",

                "current risk",

                "risk assessment",

                "risk score",

                "risk level",

                "visa risk",

                "case risk",

                "how risky is my case",

                "how risky is my visa",

                "am i at risk",

                "what is my risk",

                "what's my risk",

                "show my risk",

                "check my risk",

                "check my risk assessment",

                "assess my risk",

                "operational risk",

                "student risk"

            ]
        );

    }


    // =========================================================
    // GET CURRENT STUDENT
    // =========================================================

    function getCurrentStudent(userSysId) {

        var result = {

            found: false,

            profileSysId: "",

            student: {}

        };


        try {

            var sessionProfileSysId =
                gs.getSession()
                    .getClientData(
                        "vg_student_sys_id"
                    );


            var sessionUserName =
                gs.getSession()
                    .getClientData(
                        "vg_student_user_name"
                    );


            if (sessionProfileSysId) {

                var sessionProfile =
                    new GlideRecord(
                        "x_snc_visaguardi_0_student_profile"
                    );


                if (
                    sessionProfile.get(
                        sessionProfileSysId
                    )
                ) {

                    var sessionProfileAllowed =
                        true;


                    if (
                        sessionProfile.isValidField(
                            "user"
                        )
                    ) {

                        var linkedUser =
                            sessionProfile.getValue(
                                "user"
                            );


                        if (
                            linkedUser &&
                            linkedUser != userSysId
                        ) {

                            sessionProfileAllowed =
                                false;

                        }

                    }


                    if (
                        sessionProfileAllowed
                    ) {

                        result.found = true;

                        result.profileSysId =
                            sessionProfile.getUniqueValue();

                        result.student =
                            readStudentProfile(
                                sessionProfile
                            );

                        return result;

                    }

                }

            }


            if (sessionUserName) {

                var profileBySessionUser =
                    new GlideRecord(
                        "x_snc_visaguardi_0_student_profile"
                    );


                if (
                    profileBySessionUser.isValidField(
                        "user_name"
                    )
                ) {

                    profileBySessionUser.addQuery(
                        "user_name",
                        sessionUserName
                    );

                    profileBySessionUser.setLimit(1);

                    profileBySessionUser.query();


                    if (
                        profileBySessionUser.next()
                    ) {

                        var sessionNameAllowed =
                            true;


                        if (
                            profileBySessionUser.isValidField(
                                "user"
                            )
                        ) {

                            var linkedSessionUser =
                                profileBySessionUser.getValue(
                                    "user"
                                );


                            if (
                                linkedSessionUser &&
                                linkedSessionUser != userSysId
                            ) {

                                sessionNameAllowed =
                                    false;

                            }

                        }


                        if (
                            sessionNameAllowed
                        ) {

                            result.found = true;

                            result.profileSysId =
                                profileBySessionUser.getUniqueValue();

                            result.student =
                                readStudentProfile(
                                    profileBySessionUser
                                );

                            return result;

                        }

                    }

                }

            }


            var profile =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );


            if (
                profile.isValidField("user")
            ) {

                profile.addQuery(
                    "user",
                    userSysId
                );

                profile.setLimit(1);

                profile.query();


                if (profile.next()) {

                    result.found = true;

                    result.profileSysId =
                        profile.getUniqueValue();

                    result.student =
                        readStudentProfile(
                            profile
                        );

                    return result;
                }

            }


            profile =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );


            if (
                profile.isValidField("user_name")
            ) {

                profile.addQuery(
                    "user_name",
                    gs.getUserName()
                );

                profile.setLimit(1);

                profile.query();


                if (profile.next()) {

                    result.found = true;

                    result.profileSysId =
                        profile.getUniqueValue();

                    result.student =
                        readStudentProfile(
                            profile
                        );

                    return result;
                }

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Student Error: " +
                e.message
            );

        }


        return result;
    }


