    // =========================================================
    // EXTRACT CASE NUMBER
    // =========================================================

    function extractCaseNumber(question) {

        if (!question) {

            return "";

        }


        var match =
            String(question).match(
                /\b([A-Za-z]{2,10}\d{4,10})\b/
            );


        if (
            match &&
            match[1]
        ) {

            return match[1].toUpperCase();

        }


        return "";
    }


    // =========================================================
    // GET ALL VISA CASES FOR CURRENT STUDENT
    // =========================================================

    function getStudentVisaCases(
        profileSysId
    ) {

        var cases = [];


        if (!profileSysId) {

            return cases;

        }


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            var ownershipField =
                "";


            if (
                gr.isValidField("student")
            ) {

                ownershipField =
                    "student";

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                ownershipField =
                    "student_profile";

            }


            if (!ownershipField) {

                gs.error(
                    "VisaGuardian Security: Visa Case table has no student ownership field."
                );

                return cases;

            }


            gr.addQuery(
                ownershipField,
                profileSysId
            );


            gr.orderByDesc(
                "sys_created_on"
            );


            gr.setLimit(50);

            gr.query();


            while (
                gr.next()
            ) {

                var advisorName = "";
                var advisorEmail = "";
                var advisorSysId = "";


                if (
                    gr.isValidField("advisor")
                ) {

                    advisorSysId =
                        gr.getValue(
                            "advisor"
                        ) || "";

                }


                if (
                    !advisorSysId &&
                    gr.isValidField(
                        "assigned_advisor"
                    )
                ) {

                    advisorSysId =
                        gr.getValue(
                            "assigned_advisor"
                        ) || "";

                }


                if (
                    advisorSysId
                ) {

                    try {

                        var advisorGr =
                            new GlideRecord(
                                "x_snc_visaguardi_0_advisor_profiles"
                            );


                        if (
                            advisorGr.get(
                                advisorSysId
                            )
                        ) {

                            advisorName =
                                getField(
                                    advisorGr,
                                    [
                                        "name",
                                        "advisor_name",
                                        "full_name"
                                    ]
                                );


                            advisorEmail =
                                getField(
                                    advisorGr,
                                    [
                                        "email",
                                        "email_address"
                                    ]
                                );

                        }

                    }
                    catch (advisorError) {

                        gs.error(
                            "VisaGuardian Advisor Lookup Error: " +
                            advisorError.message
                        );

                    }

                }


                if (
                    !advisorName &&
                    gr.isValidField("advisor")
                ) {

                    advisorName =
                        gr.getDisplayValue(
                            "advisor"
                        ) || "";

                }


                if (
                    !advisorName &&
                    gr.isValidField(
                        "assigned_advisor"
                    )
                ) {

                    advisorName =
                        gr.getDisplayValue(
                            "assigned_advisor"
                        ) || "";

                }


                cases.push({

                    case_id:
                        getField(
                            gr,
                            [
                                "case_id",
                                "number",
                                "case_number"
                            ]
                        ),

                    case_type:
                        getField(
                            gr,
                            [
                                "case_type"
                            ]
                        ),

                    visa_category:
                        getField(
                            gr,
                            [
                                "visa_category",
                                "visa_type"
                            ]
                        ),

                    case_stage:
                        getField(
                            gr,
                            [
                                "case_stage",
                                "stage"
                            ]
                        ),

                    priority:
                        getField(
                            gr,
                            [
                                "priority"
                            ]
                        ),

                    status:
                        getField(
                            gr,
                            [
                                "status",
                                "state"
                            ]
                        ),

                    assigned_advisor_name:
                        advisorName,

                    assigned_advisor_email:
                        advisorEmail,

                    assigned_advisor_sys_id:
                        advisorSysId,

                    created_on:
                        getField(
                            gr,
                            [
                                "created_on",
                                "sys_created_on"
                            ]
                        ),

                    updated_on:
                        getField(
                            gr,
                            [
                                "updated_on",
                                "sys_updated_on"
                            ]
                        ),

                    sys_id:
                        gr.getUniqueValue()

                });

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Student Cases Error: " +
                e.message
            );

        }


        return cases;
    }


    // =========================================================
    // GET VISA CASE BY NUMBER
    // =========================================================

    function getVisaCaseByNumber(
        caseNumber,
        profileSysId
    ) {

        var result = {

            found: false,

            caseSysId: "",

            case: {}

        };


        if (
            !caseNumber ||
            !profileSysId
        ) {

            return result;

        }


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            var caseNumberField =
                "";


            if (
                gr.isValidField("case_id")
            ) {

                caseNumberField =
                    "case_id";

            }
            else if (
                gr.isValidField("number")
            ) {

                caseNumberField =
                    "number";

            }
            else if (
                gr.isValidField("case_number")
            ) {

                caseNumberField =
                    "case_number";

            }


            if (!caseNumberField) {

                gs.error(
                    "VisaGuardian: No case number field found."
                );

                return result;

            }


            gr.addQuery(
                caseNumberField,
                caseNumber
            );


            var ownershipField =
                "";


            if (
                gr.isValidField("student")
            ) {

                ownershipField =
                    "student";

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                ownershipField =
                    "student_profile";

            }


            if (!ownershipField) {

                gs.error(
                    "VisaGuardian Security: No ownership field found on Visa Case."
                );

                return result;

            }


            gr.addQuery(
                ownershipField,
                profileSysId
            );


            gr.setLimit(1);

            gr.query();


            if (
                gr.next()
            ) {

                result.found = true;

                result.caseSysId =
                    gr.getUniqueValue();

                result.case =
                    readVisaCase(
                        gr
                    );

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Case Lookup Error: " +
                e.message
            );

        }


        return result;
    }


    // =========================================================
    // READ VISA CASE
    // =========================================================

    function readVisaCase(gr) {

        var caseData = {};


        caseData.case_id =
            getField(
                gr,
                [
                    "case_id",
                    "number",
                    "case_number"
                ]
            );


        caseData.case_type =
            getField(
                gr,
                [
                    "case_type"
                ]
            );


        caseData.case_type_raw =
            gr.getValue(
                "case_type"
            );


        caseData.visa_category =
            getField(
                gr,
                [
                    "visa_category",
                    "visa_type"
                ]
            );


        caseData.case_stage =
            getField(
                gr,
                [
                    "case_stage",
                    "stage"
                ]
            );


        caseData.priority =
            getField(
                gr,
                [
                    "priority"
                ]
            );


        caseData.status =
            getField(
                gr,
                [
                    "status",
                    "state"
                ]
            );


        caseData.description =
            getField(
                gr,
                [
                    "description",
                    "case_description"
                ]
            );


        caseData.created_on =
            getField(
                gr,
                [
                    "created_on",
                    "sys_created_on"
                ]
            );


        caseData.updated_on =
            getField(
                gr,
                [
                    "updated_on",
                    "sys_updated_on"
                ]
            );


        var advisorSysId = "";
        var advisorName = "";
        var advisorEmail = "";


        if (
            gr.isValidField("advisor")
        ) {

            advisorSysId =
                gr.getValue(
                    "advisor"
                ) || "";

        }


        if (
            !advisorSysId &&
            gr.isValidField(
                "assigned_advisor"
            )
        ) {

            advisorSysId =
                gr.getValue(
                    "assigned_advisor"
                ) || "";

        }


        if (
            advisorSysId
        ) {

            try {

                var advisorGr =
                    new GlideRecord(
                        "x_snc_visaguardi_0_advisor_profiles"
                    );


                if (
                    advisorGr.get(
                        advisorSysId
                    )
                ) {

                    advisorName =
                        getField(
                            advisorGr,
                            [
                                "name",
                                "advisor_name",
                                "full_name"
                            ]
                        );


                    advisorEmail =
                        getField(
                            advisorGr,
                            [
                                "email",
                                "email_address"
                            ]
                        );

                }

            }
            catch (e) {

                gs.error(
                    "VisaGuardian Read Case Advisor Error: " +
                    e.message
                );

            }

        }


        if (
            !advisorName &&
            gr.isValidField("advisor")
        ) {

            advisorName =
                gr.getDisplayValue(
                    "advisor"
                ) || "";

        }


        if (
            !advisorName &&
            gr.isValidField(
                "assigned_advisor"
            )
        ) {

            advisorName =
                gr.getDisplayValue(
                    "assigned_advisor"
                ) || "";

        }


        caseData.assigned_advisor_sys_id =
            advisorSysId;

        caseData.assigned_advisor_name =
            advisorName;

        caseData.assigned_advisor_email =
            advisorEmail;


        return caseData;
    }


    // =========================================================
    // GET ADVISOR
    // =========================================================

    function getAdvisor(
        caseData,
        caseSysId
    ) {

        var advisor = {

            name: "",

            email: ""

        };


        try {

            if (
                caseData
            ) {

                advisor.name =
                    safeValue(
                        caseData.assigned_advisor_name,
                        ""
                    );


                advisor.email =
                    safeValue(
                        caseData.assigned_advisor_email,
                        ""
                    );


                if (
                    advisor.name
                ) {

                    return advisor;

                }

            }


            if (
                !caseData ||
                !caseData.case_id
            ) {

                return advisor;

            }


            var caseGr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            var caseNumberField =
                "";


            if (
                caseGr.isValidField("case_id")
            ) {

                caseNumberField =
                    "case_id";

            }
            else if (
                caseGr.isValidField("number")
            ) {

                caseNumberField =
                    "number";

            }
            else if (
                caseGr.isValidField("case_number")
            ) {

                caseNumberField =
                    "case_number";

            }


            if (!caseNumberField) {

                return advisor;

            }


            caseGr.addQuery(
                caseNumberField,
                caseData.case_id
            );


            caseGr.setLimit(1);

            caseGr.query();


            if (
                !caseGr.next()
            ) {

                return advisor;

            }


            var advisorSysId =
                "";


            if (
                caseGr.isValidField("advisor")
            ) {

                advisorSysId =
                    caseGr.getValue(
                        "advisor"
                    ) || "";

            }


            if (
                !advisorSysId &&
                caseGr.isValidField(
                    "assigned_advisor"
                )
            ) {

                advisorSysId =
                    caseGr.getValue(
                        "assigned_advisor"
                    ) || "";

            }


            if (
                advisorSysId
            ) {

                var advisorGr =
                    new GlideRecord(
                        "x_snc_visaguardi_0_advisor_profiles"
                    );


                if (
                    advisorGr.get(
                        advisorSysId
                    )
                ) {

                    advisor.name =
                        getField(
                            advisorGr,
                            [
                                "name",
                                "advisor_name",
                                "full_name"
                            ]
                        );


                    advisor.email =
                        getField(
                            advisorGr,
                            [
                                "email",
                                "email_address"
                            ]
                        );

                }

            }


            if (
                !advisor.name &&
                caseGr.isValidField("advisor")
            ) {

                advisor.name =
                    caseGr.getDisplayValue(
                        "advisor"
                    ) || "";

            }


            if (
                !advisor.name &&
                caseGr.isValidField(
                    "assigned_advisor"
                )
            ) {

                advisor.name =
                    caseGr.getDisplayValue(
                        "assigned_advisor"
                    ) || "";

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Advisor Error: " +
                e.message
            );

        }


        return advisor;
    }


    // =========================================================
    // DOCUMENT QUESTION DETECTOR
    // =========================================================

    function isDocumentQuestion(
        normalizedQuestion
    ) {

        if (!normalizedQuestion) {

            return false;

        }


        return containsAny(
            normalizedQuestion,
            [

                "my documents",
                "my document",
                "document status",
                "document information",
                "document details",
                "document checklist",

                "what documents do i need",
                "what documents do i need for",
                "which documents do i need",
                "which documents are required",
                "what documents are required",
                "required documents",
                "documents required",
                "documents i need",
                "documents needed",

                "what documents have i submitted",
                "which documents have i submitted",
                "what documents did i submit",
                "which documents did i submit",
                "what are the documents submitted",  
                "documents submitted",
                "documents i submitted",
                "submitted documents",
                "uploaded documents",
                "what have i uploaded",
                "what did i upload",
                "have i submitted",
                "did i submit",
                "have i uploaded",

                "what documents am i missing",
                "which documents am i missing",
                "what are the missing documents",
                "what are the documents missing",
                "what am i missing",
                "which documents are missing",
                "what documents are missing",
                "missing documents",
                "documents missing",
                "pending documents",
                "documents pending",

                "check my documents",
                "check my document",
                "can you check my documents",
                "can you check my document",
                "review my documents",
                "review my document",
                "check document status",
                "check my document status",

                "are my documents complete",
                "are my documents completed",
                "is my document complete",
                "are all my documents submitted",
                "is everything submitted",
                "is my document status complete"

            ]
        );

    }


    // =========================================================
    // GET STUDENT DOCUMENTS
    // =========================================================

    function getStudentDocuments(
        profileSysId,
        caseSysId,
        caseTypeRaw
    ) {

        var documents = [];


        if (
            !caseSysId
        ) {

            return documents;

        }


        try {

            var requiredLabels = [];


            var configGr =
                new GlideRecord(
                    "x_snc_visaguardi_0_document_configuration"
                );


            if (
                !configGr.isValid()
            ) {

                gs.error(
                    "VisaGuardian: Document Configuration table is invalid."
                );

                return documents;

            }


            configGr.addQuery(
                "visa_category",
                caseTypeRaw
            );


            configGr.addQuery(
                "active",
                true
            );


            configGr.addQuery(
                "required",
                true
            );


            configGr.query();


            while (
                configGr.next()
            ) {

                requiredLabels.push(
                    configGr.getDisplayValue(
                        "document_type"
                    )
                );

            }


            var labelLookup = {};


            var configGr2 =
                new GlideRecord(
                    "x_snc_visaguardi_0_document_configuration"
                );


            if (
                configGr2.isValid()
            ) {

                configGr2.query();


                while (
                    configGr2.next()
                ) {

                    var rawType =
                        String(
                            configGr2.getValue(
                                "document_type"
                            )
                        ).toLowerCase();


                    var displayLabel =
                        configGr2.getDisplayValue(
                            "document_type"
                        );


                    labelLookup[rawType] =
                        displayLabel;

                }

            }


            var submittedLabels = [];


            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_document"
                );


            if (
                !gr.isValid()
            ) {

                gs.error(
                    "VisaGuardian: Visa Document table is invalid."
                );

                return documents;

            }


            gr.addQuery(
                "visa_case",
                caseSysId
            );


            gr.query();


            while (
                gr.next()
            ) {

                var rawDocType =
                    String(
                        gr.getValue(
                            "document_type"
                        )
                    );


                var displayDocType =
                    gr.getDisplayValue(
                        "document_type"
                    );


                var normalizedType =
                    labelLookup[
                        rawDocType.toLowerCase()
                    ] ||
                    displayDocType;


                var docStatus =
                    gr.getDisplayValue(
                        "document_status"
                    );


                var verificationStatusRaw =
                    gr.getValue(
                        "verification_status"
                    );


                var verificationStatusLabel =
                    gr.getDisplayValue(
                        "verification_status"
                    );


                submittedLabels.push(
                    normalizedType
                );


                documents.push({

                    name:
                        normalizedType,

                    status:
                        docStatus,

                    verification_status:
                        verificationStatusLabel,

                    required:
                        requiredLabels.indexOf(
                            normalizedType
                        ) !== -1,

                    submitted:
                        true,

                    missing:
                        (
                            verificationStatusRaw ===
                            "rejected"
                        ),

                    pending:
                        (
                            verificationStatusRaw ===
                            "pending" ||
                            verificationStatusRaw ===
                            "under_review"
                        ),

                    sys_id:
                        gr.getUniqueValue()

                });

            }


            requiredLabels.forEach(
                function (label) {

                    if (
                        submittedLabels.indexOf(
                            label
                        ) === -1
                    ) {

                        documents.push({

                            name:
                                label,

                            status:
                                "Not Submitted",

                            verification_status:
                                "Not Submitted",

                            required:
                                true,

                            submitted:
                                false,

                            missing:
                                true,

                            pending:
                                false

                        });

                    }

                }
            );


        }
        catch (e) {

            gs.error(
                "VisaGuardian Document Error: " +
                e.message
            );

        }


        return documents;
    }


    // =========================================================
    // BUILD DOCUMENT RESPONSE
    // =========================================================

    function buildDocumentResponse(
        question,
        caseNumber,
        documents,
        visaCase
    ) {

        var normalized =
            String(
                question || ""
            ).toLowerCase();


        var requiredDocuments = [];
        var submittedDocuments = [];
        var missingDocuments = [];
        var pendingDocuments = [];


        for (
            var i = 0;
            i < documents.length;
            i++
        ) {

            var doc =
                documents[i];


            var status =
                String(
                    doc.status || ""
                ).toLowerCase();


            var required =
                doc.required === true;


            var submitted =
                doc.submitted === true;


            var missing =
                doc.missing === true;


            var pending =
                doc.pending === true;


            if (required) {

                requiredDocuments.push(
                    doc
                );

            }


            if (submitted) {

                submittedDocuments.push(
                    doc
                );

            }


            if (missing) {

                missingDocuments.push(
                    doc
                );

            }


            if (pending) {

                pendingDocuments.push(
                    doc
                );

            }


            if (
                !required &&
                !submitted &&
                !missing &&
                !pending
            ) {

                if (
                    status.indexOf("submitted") !== -1 ||
                    status.indexOf("uploaded") !== -1 ||
                    status.indexOf("received") !== -1 ||
                    status.indexOf("approved") !== -1
                ) {

                    submittedDocuments.push(
                        doc
                    );

                }
                else if (
                    status.indexOf("missing") !== -1 ||
                    status.indexOf("not submitted") !== -1 ||
                    status.indexOf("not received") !== -1
                ) {

                    missingDocuments.push(
                        doc
                    );

                }
                else if (
                    status.indexOf("pending") !== -1 ||
                    status.indexOf("review") !== -1
                ) {

                    pendingDocuments.push(
                        doc
                    );

                }

            }

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents do i need",
                    "which documents do i need",
                    "documents i need",
                    "documents needed",
                    "what documents are required",
                    "which documents are required",
                    "required documents",
                    "documents required"
                ]
            )
        ) {

            return showDocumentList(
                "Required Documents",
                "Here are the required document records available for your case " +
                caseNumber +
                ":",
                requiredDocuments,
                "No required document records were found for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents have i submitted",
                    "which documents have i submitted",
                    "what documents did i submit",
                    "which documents did i submit",
                    "documents i submitted",
                    "submitted documents",
                    "uploaded documents",
                    "what have i uploaded",
                    "what did i upload",
                    "have i submitted",
                    "did i submit",
                    "have i uploaded"
                ]
            )
        ) {

            return showDocumentList(
                "Submitted Documents",
                "Here are the documents recorded as submitted or uploaded for case " +
                caseNumber +
                ":",
                submittedDocuments,
                "No submitted or uploaded document records were found for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents am i missing",
                    "which documents am i missing",
                    "what am i missing",
                    "which documents are missing",
                    "what documents are missing",
                    "missing documents",
                    "documents missing"
                ]
            )
        ) {

            return showDocumentList(
                "Missing Documents",
                "Here are the document records currently marked as missing for case " +
                caseNumber +
                ":",
                missingDocuments,
                "No documents are currently marked as missing for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "pending documents",
                    "documents pending"
                ]
            )
        ) {

            return showDocumentList(
                "Pending Documents",
                "Here are the documents currently pending or under review for case " +
                caseNumber +
                ":",
                pendingDocuments,
                "No pending document records were found for this case."
            );

        }


        var allDocumentBullets = [];


        if (
            documents &&
            documents.length > 0
        ) {

            for (
                var d = 0;
                d < documents.length;
                d++
            ) {

                var currentDocument =
                    documents[d];


                var line =
                    safeValue(
                        currentDocument.name,
                        "Document"
                    );


                if (
                    currentDocument.status
                ) {

                    line +=
                        " — Status: " +
                        currentDocument.status;

                }


                if (
                    currentDocument.required
                ) {

                    line +=
                        " — Required";

                }


                if (
                    currentDocument.submitted
                ) {

                    line +=
                        " — Submitted";

                }


                if (
                    currentDocument.missing
                ) {

                    line +=
                        " — Missing";

                }


                if (
                    currentDocument.pending
                ) {

                    line +=
                        " — Pending";

                }


                allDocumentBullets.push(
                    line
                );

            }

        }
        else {

            allDocumentBullets.push(
                "No document records were found for this case."
            );

        }


        data.success = true;

        data.title =
            "Document Check";

        data.introduction =
            "Here is the current document information for case " +
            caseNumber +
            ":";

        data.sections = [

            {

                title:
                    "Document Status",

                text: "",

                bullets:
                    allDocumentBullets,

                steps: []

            }

        ];


        var summaryText =
            "Total document records: " +
            documents.length +
            ".";


        if (
            requiredDocuments.length > 0
        ) {

            summaryText +=
                " Required: " +
                requiredDocuments.length +
                ".";

        }


        if (
            submittedDocuments.length > 0
        ) {

            summaryText +=
                " Submitted/uploaded: " +
                submittedDocuments.length +
                ".";

        }


        if (
            missingDocuments.length > 0
        ) {

            summaryText +=
                " Missing: " +
                missingDocuments.length +
                ".";

        }


        if (
            pendingDocuments.length > 0
        ) {

            summaryText +=
                " Pending: " +
                pendingDocuments.length +
                ".";

        }


        data.summary =
            summaryText;


        return;
    }


    // =========================================================
    // SHOW DOCUMENT LIST
    // =========================================================

    function showDocumentList(
        title,
        introduction,
        documentList,
        emptyMessage
    ) {

        var bullets = [];


        if (
            documentList &&
            documentList.length > 0
        ) {

            for (
                var i = 0;
                i < documentList.length;
                i++
            ) {

                var doc =
                    documentList[i];


                var line =
                    safeValue(
                        doc.name,
                        "Document"
                    );


                if (
                    doc.status
                ) {

                    line +=
                        " — Status: " +
                        doc.status;

                }


                bullets.push(
                    line
                );

            }

        }
        else {

            bullets.push(
                emptyMessage
            );

        }


        data.success = true;

        data.title =
            title;

        data.introduction =
            introduction;

        data.sections = [

            {

                title:
                    title,

                text: "",

                bullets:
                    bullets,

                steps: []

            }

        ];


        data.summary =
            documentList &&
            documentList.length > 0
                ?
                "The information above is based on document records associated with your verified visa case."
                :
                emptyMessage;


        return;
    }


    // =========================================================
    // SEARCH KNOWLEDGE BASE
    // =========================================================

    function searchKnowledgeBase(
        question
    ) {

        var result = {

            found: false,

            sections: [],

            summary: "",

            articles: []

        };


        try {

            var kb =
                new GlideRecord(
                    "kb_knowledge"
                );


            kb.addQuery(
                "workflow_state",
                "published"
            );


            var q =
                kb.addQuery(
                    "short_description",
                    "CONTAINS",
                    question
                );


            q.addOrCondition(
                "text",
                "CONTAINS",
                question
            );


            kb.orderByDesc(
                "sys_updated_on"
            );


            kb.setLimit(1);

            kb.query();


            if (
                kb.next()
            ) {

                result.found = true;


                var articleText =
                    kb.getValue(
                        "text"
                    ) || "";


                articleText =
                    cleanText(
                        articleText
                    );


                var points =
                    convertToPoints(
                        articleText
                    );


                result.sections = [

                    {

                        title:
                            "Important Points",

                        text: "",

                        bullets:
                            points,

                        steps: []

                    }

                ];


                result.summary =
                    "Review the points above and follow the applicable requirements for your situation.";

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian KB Error: " +
                e.message
            );

        }


        return result;
    }


    // =========================================================
    // GEMINI FALLBACK
    // =========================================================

    function callGemini(
        question,
        student,
        visaCase,
        advisor,
        documents
    ) {

        var result = {

            success: false,

            answer: "",

            error: ""

        };


        try {

            var rm =
                new sn_ws.RESTMessageV2(
                    "VisaGuardian Gemini AI",
                    "Generate Visa AI Analysis"
                );


            var studentContext =

                "Student Name: " +
                safeValue(student.name) +

                "\nStudent ID: " +
                safeValue(student.student_id) +

                "\nUniversity: " +
                safeValue(student.university_name) +

                "\nDegree Program: " +
                safeValue(student.degree_program) +

                "\nDegree Level: " +
                safeValue(student.degree_level) +

                "\nCurrent Semester: " +
                safeValue(student.current_semester) +

                "\nIntake Year: " +
                safeValue(student.intake_year) +

                "\nVisa Type: " +
                safeValue(student.visa_type) +

                "\nVisa Status: " +
                safeValue(student.current_visa_status) +

                "\nSEVIS ID: " +
                safeValue(student.sevis_id) +

                "\nVisa Expiry Date: " +
                safeValue(student.visa_expiry_date) +

                "\nPassport Expiry Date: " +
                safeValue(student.passport_expiry_date);


            var caseContext = "";


            if (
                visaCase &&
                visaCase.case_id
            ) {

                caseContext =

                    "Case ID: " +
                    safeValue(visaCase.case_id) +

                    "\nCase Type: " +
                    safeValue(visaCase.case_type) +

                    "\nVisa Category: " +
                    safeValue(visaCase.visa_category) +

                    "\nCase Stage: " +
                    safeValue(visaCase.case_stage) +

                    "\nPriority: " +
                    safeValue(visaCase.priority) +

                    "\nStatus: " +
                    safeValue(visaCase.status) +

                    "\nAssigned Advisor: " +
                    safeValue(visaCase.assigned_advisor_name) +

                    "\nAdvisor Email: " +
                    safeValue(visaCase.assigned_advisor_email);

            }
            else {

                caseContext =
                    "No specific visa case has been selected.";

            }


            var advisorContext = "";


            if (
                advisor &&
                advisor.name
            ) {

                advisorContext =

                    "Advisor: " +
                    safeValue(advisor.name) +

                    "\nAdvisor Email: " +
                    safeValue(advisor.email);

            }
            else {

                advisorContext =
                    "No specific case advisor has been selected.";

            }


            var documentContext =
                "";


            if (
                documents &&
                documents.length > 0
            ) {

                documentContext =
                    "\n\nDOCUMENTS:\n";


                for (
                    var d = 0;
                    d < documents.length;
                    d++
                ) {

                    documentContext +=

                        "\n- " +
                        safeValue(
                            documents[d].name,
                            "Document"
                        ) +
                        " | Status: " +
                        safeValue(
                            documents[d].status,
                            "Unknown"
                        ) +
                        " | Required: " +
                        String(
                            documents[d].required
                        ) +
                        " | Submitted: " +
                        String(
                            documents[d].submitted
                        ) +
                        " | Missing: " +
                        String(
                            documents[d].missing
                        ) +
                        " | Pending: " +
                        String(
                            documents[d].pending
                        );

                }

            }
            else {

                documentContext =
                    "\n\nNo specific document records have been selected.";

            }


            var prompt =

                "You are VisaGuardian AI. " +

                "Answer the student's question about international " +
                "student visa compliance. " +

                "Use the supplied student, visa case, advisor, " +
                "and document context only when relevant. " +

                "Never invent student information. " +

                "Never reveal information belonging to another student. " +

                "Do not mention Gemini. " +

                "Do not mention the Knowledge Base. " +

                "Do not mention internal systems. " +

                "Give concise, useful factual guidance. " +

                "Only provide personal student information that is " +
                "directly relevant to the student's question. " +

                "If no specific visa case has been selected, " +
                "do not assume or invent a current case. " +

                "If document information is not available, do not invent " +
                "document names or statuses. " +

                "Use numbered points when appropriate. " +

                "If the question requires steps, provide the steps " +
                "in the correct order. " +

                "For important immigration decisions, advise the " +
                "student to confirm requirements with their university " +
                "international student advisor or appropriate " +
                "immigration authority. " +

                "\n\nCURRENT STUDENT:\n" +
                studentContext +

                "\n\nSELECTED VISA CASE:\n" +
                caseContext +

                "\n\nSELECTED CASE ADVISOR:\n" +
                advisorContext +

                documentContext +

                "\n\nSTUDENT QUESTION:\n" +
                question;


            var requestBody = {

                contents: [

                    {

                        parts: [

                            {

                                text:
                                    prompt

                            }

                        ]

                    }

                ],

                generationConfig: {

                    temperature: 0.2,

                    maxOutputTokens: 1200

                }

            };


            rm.setRequestBody(
                JSON.stringify(
                    requestBody
                )
            );


            var response =
                rm.execute();


            var status =
                response.getStatusCode();


            var body =
                response.getBody();


            if (
                status < 200 ||
                status >= 300
            ) {

                result.error =
                    "HTTP " +
                    status;


                gs.error(
                    "VisaGuardian AI Error: " +
                    body
                );


                return result;

            }


            var json =
                JSON.parse(
                    body
                );


            var answer = "";


            if (
                json.candidates &&
                json.candidates.length > 0
            ) {

                var candidate =
                    json.candidates[0];


                if (
                    candidate.content &&
                    candidate.content.parts
                ) {

                    for (
                        var i = 0;
                        i <
                        candidate.content.parts.length;
                        i++
                    ) {

                        if (
                            candidate.content.parts[i].text
                        ) {

                            answer +=
                                candidate.content.parts[i].text;

                        }

                    }

                }

            }


            if (!answer) {

                result.error =
                    "Empty response.";

                return result;

            }


            result.success = true;

            result.answer =
                cleanText(
                    answer
                );


            return result;

        }
        catch (e) {

            result.error =
                e.message;


            gs.error(
                "VisaGuardian AI Exception: " +
                e.message
            );


            return result;

        }

    }


    // =========================================================
    // CREATE SUPPORT TICKET
    // =========================================================

    function createSupportTicket(
        profileSysId,
        question
    ) {

        var result = {

            success: false,

            ticketNumber: ""

        };


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            if (
                !gr.isValid()
            ) {

                return result;

            }


            gr.initialize();


            if (
                gr.isValidField("student")
            ) {

                gr.setValue(
                    "student",
                    profileSysId
                );

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                gr.setValue(
                    "student_profile",
                    profileSysId
                );

            }


            if (
                gr.isValidField("case_type")
            ) {

                gr.setValue(
                    "case_type",
                    "General Inquiry"
                );

            }


            if (
                gr.isValidField("priority")
            ) {

                gr.setValue(
                    "priority",
                    "4 - Low"
                );

            }


            if (
                gr.isValidField("status")
            ) {

                gr.setValue(
                    "status",
                    "Open"
                );

            }
            else if (
                gr.isValidField("state")
            ) {

                gr.setValue(
                    "state",
                    "Open"
                );

            }


            if (
                gr.isValidField("description")
            ) {

                gr.setValue(
                    "description",
                    "AI Assistant could not directly answer the following student question:\n\n" +
                    question
                );

            }
            else if (
                gr.isValidField(
                    "case_description"
                )
            ) {

                gr.setValue(
                    "case_description",
                    "AI Assistant could not directly answer the following student question:\n\n" +
                    question
                );

            }


            var newSysId =
                gr.insert();


            if (newSysId) {

                result.success = true;

                result.ticketNumber =
                    getField(
                        gr,
                        [
                            "case_id",
                            "number",
                            "case_number"
                        ]
                    ) ||
                    newSysId;

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Ticket Creation Error: " +
                e.message
            );

        }


        return result;
    }


