            );

        }


        if (
            visaCase.description
        ) {

            points.push(
                "Case description: " +
                visaCase.description
            );

        }


        return points.join(
            "\n"
        );

    }


    // =========================================================
    // ALL CASES SUMMARY
    // =========================================================

    function buildAllCasesSummary(
        student,
        cases
    ) {

        var points = [];


        points.push(
            "Student: " +
            safeValue(
                student.name
            )
        );


        points.push(
            "Total visa cases: " +
            cases.length
        );


        for (
            var i = 0;
            i < cases.length;
            i++
        ) {

            var currentCase =
                cases[i];


            var caseSummary =

                "Case " +
                (i + 1) +
                ": " +

                safeValue(
                    currentCase.case_id,
                    "Unknown"
                ) +

                " — Type: " +

                safeValue(
                    currentCase.case_type,
                    "Not available"
                ) +

                " — Status: " +

                safeValue(
                    currentCase.case_stage,
                    "Not available"
                ) +

                " — Priority: " +

                safeValue(
                    currentCase.priority,
                    "Not available"
                );


            if (
                currentCase.assigned_advisor_name
            ) {

                caseSummary +=
                    " — Advisor: " +
                    safeValue(
                        currentCase.assigned_advisor_name
                    );

            }


            if (
                currentCase.visa_category
            ) {

                caseSummary +=
                    " — Visa Category: " +
                    safeValue(
                        currentCase.visa_category
                    );

            }


            points.push(
                caseSummary
            );

        }


        var openCount = 0;
        var rejectedCount = 0;


        for (
            var j = 0;
            j < cases.length;
            j++
        ) {

            var stage =
                String(
                    cases[j].case_stage || ""
                ).toLowerCase();


            var status =
                String(
                    cases[j].status || ""
                ).toLowerCase();


            if (
                stage.indexOf("reject") !== -1 ||
                status.indexOf("reject") !== -1
            ) {

                rejectedCount++;

            }


            if (
                status == "open" ||
                status.indexOf("open") !== -1
            ) {

                openCount++;

            }

        }


        points.push(
            "Overall case status: " +
            openCount +
            " case(s) are currently open."
        );


        if (
            rejectedCount > 0
        ) {

            points.push(
                "Attention: " +
                rejectedCount +
                " case(s) contain rejection-related status or stage information."
            );

        }


        points.push(
            "Recommended next step: Review each case individually for its specific requirements or rejection details and consult your assigned international student advisor before making important immigration decisions."
        );


        return points.join(
            "\n"
        );

    }


    // =========================================================
    // FIELD READER
    // =========================================================

    function getField(
        gr,
        fieldNames
    ) {

        if (
            !gr ||
            !fieldNames
        ) {

            return "";

        }


        for (
            var i = 0;
            i < fieldNames.length;
            i++
        ) {

            var field =
                fieldNames[i];


            if (
                gr.isValidField(field)
            ) {

                var value =
                    gr.getDisplayValue(
                        field
                    );


                if (
                    value !== null &&
                    value !== undefined &&
                    String(value).trim() !== ""
                ) {

                    return String(
                        value
                    ).trim();

                }

            }

        }


        return "";
    }


    // =========================================================
    // SAFE VALUE
    // =========================================================

    function safeValue(
        value,
        fallback
    ) {

        if (
            value === null ||
            value === undefined ||
            String(value).trim() === ""
        ) {

            return fallback ||
                "Not available";

        }


        return String(
            value
        );

    }


    // =========================================================
    // QUESTION MATCHING
    // =========================================================

    function containsAny(
        text,
        words
    ) {

        if (!text) {

            return false;

        }


        for (
            var i = 0;
            i < words.length;
            i++
        ) {

            if (
                text.indexOf(
                    words[i]
                ) !== -1
            ) {

                return true;

            }

        }


        return false;

    }


    // =========================================================
    // CONVERT TEXT TO POINTS
    // =========================================================

    function convertToPoints(
        text
    ) {

        if (!text) {

            return [];

        }


        text =
            cleanText(
                text
            );


        var points = [];


        var lines =
            text.split(
                /\r?\n/
            );


        for (
            var i = 0;
            i < lines.length;
            i++
        ) {

            var line =
                String(
                    lines[i]
                ).trim();


            if (!line) {

                continue;

            }


            line =
                line.replace(
                    /^\s*(?:\d+[\.\)]|[-•*])\s*/,
                    ""
                );


            if (!line) {

                continue;

            }


            if (
                line.toLowerCase()
                    .indexOf(
                        "gemini"
                    ) === 0
            ) {

                continue;

            }


            if (
                line.toLowerCase()
                    .indexOf(
                        "knowledge base"
                    ) === 0
            ) {

                continue;

            }


            if (
                line.length > 240
            ) {

                var sentences =
                    line.split(
                        /(?<=[.!?])\s+/
                    );


                for (
                    var j = 0;
                    j < sentences.length;
                    j++
                ) {

                    var sentence =
                        sentences[j].trim();


                    if (
                        sentence.length > 10
                    ) {

                        points.push(
                            sentence
                        );

                    }

                }

            }
            else {

                points.push(
                    line
                );

            }

        }


        var unique = [];

        var seen = {};


        for (
            var k = 0;
            k < points.length;
            k++
        ) {

            var point =
                points[k].trim();


            if (!point) {

                continue;

            }


            var key =
                point.toLowerCase();


            if (!seen[key]) {

                seen[key] = true;

                unique.push(
                    point
                );

            }

        }


        if (
            unique.length > 20
        ) {

            unique =
                unique.slice(
                    0,
                    20
                );

        }


        return unique;

    }


    // =========================================================
    // CLEAN TEXT
    // =========================================================

    function cleanText(
        text
    ) {

        if (!text) {

            return "";

        }


        text =
            String(
                text
            );


        text =
            text.replace(
                /#[a-zA-Z0-9_-]+\s*\{[^}]*\}/g,
                ""
            );


        text =
            text.replace(
                /<style[\s\S]*?<\/style>/gi,
                ""
            );


        text =
            text.replace(
                /<script[\s\S]*?<\/script>/gi,
                ""
            );


        text =
            text.replace(
                /<[^>]+>/g,
                ""
            );


        text =
            text.replace(
                /```/g,
                ""
            );


        text =
            text.replace(
                /\bGemini AI\b/gi,
                ""
            );


        text =
            text.replace(
                /\bGemini\b/gi,
                ""
            );


        text =
            text.replace(
                /\bKnowledge Base\b/gi,
                ""
            );


        text =
            text.replace(
                /[ \t]+/g,
                " "
            );


        text =
            text.replace(
                /\n{3,}/g,
                "\n\n"
            );


        return text.trim();

    }


})();
